// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ───────────────────────────────
 // green plane x=1   → PlaneGeometry(4,4), rotY 90°, MeshBasicMaterial #22B14C, DoubleSide, opacity .88
 // red   plane y=-2  → PlaneGeometry(4,4), no rot,   MeshBasicMaterial #D62027, DoubleSide, opacity .88
 // blue  plane z=2   → PlaneGeometry(4,4), rotX -90°,MeshBasicMaterial #1878A0, DoubleSide, opacity .88
 // green∩red line    → Line, 2 pts, dark green/red mix, depthTest off
 // green∩blue line   → Line, 2 pts, dark green/blue mix
 // red∩blue line     → Line, 2 pts, dark red/blue mix
 // solution dot      → SphereGeometry(0.07), black, depthTest off
 // leader line       → Line, 2 pts, black thin
 // mismatch connector→ Line dashed, amber, dot → red sheet (printed mode only)
 // focus arrows ×3   → ArrowHelper along each plane normal (hidden until focus)
 // labels            → addLabel HTML: (1,-1,2) black · x=1 green · y=-2 red · z=2 blue
 ------------------------------------------------------------------------ */

// math (x,y,z) with z up  →  three.js (x, z, y)
const V = (x, y, z) => new THREE.Vector3(x, z, y);

const COL = { green: 0x22B14C, red: 0xD62027, blue: 0x1878A0 };
function mixDark(a, b) {
  const c = new THREE.Color(a).lerp(new THREE.Color(b), 0.5);
  c.multiplyScalar(0.55);
  return c;
}

/* ── Planes ──────────────────────────────────────────────────────────── */
function makePlane(color, normalAxis, center) {
  const mat = new THREE.MeshBasicMaterial({
    color, side: THREE.DoubleSide, transparent: true, opacity: 0.88,
    depthWrite: true, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  });
  const m = new THREE.Mesh(new THREE.PlaneGeometry(4, 4), mat);
  if (normalAxis === 'x') m.rotation.y = Math.PI / 2;   // normal → +X
  if (normalAxis === 'y') m.rotation.x = -Math.PI / 2;  // normal → +Y (three up = math z)
  m.position.copy(center);
  scene.add(m);
  return m;
}

// green: x = 1, y∈[-3,1], z∈[0,4]   → three centre (1, 2, -1), normal +X
const meshX = makePlane(COL.green, 'x', V(1, -1, 2));
// red:   y = -2, x∈[-1,3], z∈[0,4]  → three centre (1, 2, -2), normal +Z
const meshY = makePlane(COL.red, 'z', V(1, -2, 2));
// blue:  z = 2, x∈[-1,3], y∈[-3,1]  → three centre (1, 2, -1), normal +Y
const meshZ = makePlane(COL.blue, 'y', V(1, -1, 2));

/* ── Intersection lines ──────────────────────────────────────────────── */
function makeLine(col, a, b, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints([a.clone(), b.clone()]);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: col, dashSize: 0.14, gapSize: 0.1, depthTest: false })
    : new THREE.LineBasicMaterial({ color: col, depthTest: false });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  l.renderOrder = 6;
  scene.add(l);
  return {
    line: l,
    set(p, q) {
      const pos = l.geometry.attributes.position;
      pos.setXYZ(0, p.x, p.y, p.z);
      pos.setXYZ(1, q.x, q.y, q.z);
      pos.needsUpdate = true;
      if (dashed) l.computeLineDistances();
      l.geometry.computeBoundingSphere();
    }
  };
}

const lnGR = makeLine(mixDark(COL.green, COL.red), V(1, -2, 0), V(1, -2, 4));
const lnGB = makeLine(mixDark(COL.green, COL.blue), V(1, -3, 2), V(1, 1, 2));
const lnRB = makeLine(mixDark(COL.red, COL.blue), V(-1, -2, 2), V(3, -2, 2));

/* ── Solution dot, leader, mismatch connector ────────────────────────── */
const dot = new THREE.Mesh(
  new THREE.SphereGeometry(0.075, 20, 16),
  new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false })
);
dot.renderOrder = 12;
dot.position.copy(V(1, -1, 2));
scene.add(dot);

const LEAD = new THREE.Vector3(0.9, 2.2, -0.9);  // up-and-right on screen
const leader = makeLine(0x000000, dot.position, dot.position.clone().add(LEAD));
const connector = makeLine(0xE8A317, V(1, -1, 2), V(1, -2, 2), true);

/* ── Camera (after all core geometry) ────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.68
});
controls.minPolarAngle = 0.08;
controls.maxPolarAngle = Math.PI / 2 - 0.03;
document.getElementById('btnReset').style.display = '';

/* ── Focus arrows (added after fit; short, inside existing bounds) ───── */
function makeArrow(dir, origin, color) {
  const a = new THREE.ArrowHelper(dir.clone().normalize(), origin.clone(), 1.5, color, 0.38, 0.22);
  a.visible = false;
  a.renderOrder = 8;
  scene.add(a);
  return a;
}
const arrX = makeArrow(new THREE.Vector3(1, 0, 0), V(1, -1, 2), COL.green);
const arrY = makeArrow(new THREE.Vector3(0, 0, 1), V(1, -2, 2), COL.red);
const arrZ = makeArrow(new THREE.Vector3(0, 1, 0), V(1, -1, 2), COL.blue);

/* ── Labels ──────────────────────────────────────────────────────────── */
const labPoint = addLabel('(1, &minus;1, 2)', dot.position.clone().add(LEAD),
  { fontSize: '15px', offset: [26, -8] });
const labX = addLabel('<i>x</i> = 1', V(1, -3, 4),
  { color: '#22B14C', fontSize: '15px', offset: [28, -12] });
const labY = addLabel('<i>y</i> = &minus;2', V(1, -2, -0.4),
  { color: '#D62027', fontSize: '15px', offset: [0, 16] });
const labZ = addLabel('<i>z</i> = 2', V(3, -3, 2),
  { color: '#1878A0', fontSize: '15px', offset: [34, 0] });
const labWarn = addLabel('point not on <i>y</i> = &minus;2', V(1, -1.5, 2),
  { color: '#8a5a00', fontSize: '11px', background: 'rgba(255,224,150,0.92)', offset: [-14, 24] });
const labArrX = addLabel('<i>x</i> pinned at 1 &nbsp;(<i>y</i>, <i>z</i> free)', V(2.5, -1, 2),
  { color: '#1a8c3c', fontSize: '12px', bold: true, offset: [0, -16] });
const labArrY = addLabel('<i>y</i> pinned at &minus;2 &nbsp;(<i>x</i>, <i>z</i> free)', V(1, -0.5, 2),
  { color: '#c31a20', fontSize: '12px', bold: true, offset: [0, -16] });
const labArrZ = addLabel('<i>z</i> pinned at 2 &nbsp;(<i>x</i>, <i>y</i> free)', V(1, -1, 3.5),
  { color: '#14688c', fontSize: '12px', bold: true, offset: [0, -16] });

function setLabVis(entry, on) { entry.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── State + geometry update ─────────────────────────────────────────── */
const state = { redY: -2, dotY: -1, mode: 'printed', focus: null, showX: true, showY: true, showZ: true };

function applyGeometry() {
  meshY.position.z = state.redY;
  dot.position.z = state.dotY;

  lnGR.set(V(1, state.redY, 0), V(1, state.redY, 4));
  lnGB.set(V(1, -3, 2), V(1, 1, 2));
  lnRB.set(V(-1, state.redY, 2), V(3, state.redY, 2));

  leader.set(dot.position, dot.position.clone().add(LEAD));
  connector.set(dot.position, V(1, state.redY, 2));

  labPoint.pos.copy(dot.position).add(LEAD);
