// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ───────────────────────────────
 // green plane x=1   → PlaneGeometry(4,4), rotY 90°, MeshBasicMaterial #22B14C, DoubleSide, opacity .88
 // red   plane y=-2  → PlaneGeometry(4,4), no rot,   MeshBasicMaterial #D62027, DoubleSide, opacity .88
 // blue  plane z=2   → PlaneGeometry(4,4), rotX -90°,MeshBasicMaterial #1878A0, DoubleSide, opacity .88
 // green∩red line    → Line, 2 pts, dark green/red mix, depthTest off
 // green∩blue line   → Line, 2 pts, dark green/blue mix
 // red∩blue line     → Line, 2 pts, dark red/blue mix
 // solution dot      → SphereGeometry(0.07), black, depthTest off
 // leader line       → Line, 2 pts, black thin
 // mismatch connector→ Line dashed, amber, dot → red sheet (printed mode only)
 // focus arrows ×3   → ArrowHelper along each plane normal (hidden until focus)
 // labels            → addLabel HTML: (1,-1,2) black · x=1 green · y=-2 red · z=2 blue
 ------------------------------------------------------------------------ */

// math (x,y,z) with z up  →  three.js (x, z, y)
const V = (x, y, z) => new THREE.Vector3(x, z, y);

const COL = { green: 0x22B14C, red: 0xD62027, blue: 0x1878A0 };
function mixDark(a, b) {
  const c = new THREE.Color(a).lerp(new THREE.Color(b), 0.5);
  c.multiplyScalar(0.55);
  return c;
}

/* ── Planes ──────────────────────────────────────────────────────────── */
function makePlane(color, normalAxis, center) {
  const mat = new THREE.MeshBasicMaterial({
    color, side: THREE.DoubleSide, transparent: true, opacity: 0.88,
    depthWrite: true, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  });
  const m = new THREE.Mesh(new THREE.PlaneGeometry(4, 4), mat);
  if (normalAxis === 'x') m.rotation.y = Math.PI / 2;   // normal → +X
  if (normalAxis === 'y') m.rotation.x = -Math.PI / 2;  // normal → +Y (three up = math z)
  m.position.copy(center);
  scene.add(m);
  return m;
}

// green: x = 1, y∈[-3,1], z∈[0,4]   → three centre (1, 2, -1), normal +X
const meshX = makePlane(COL.green, 'x', V(1, -1, 2));
// red:   y = -2, x∈[-1,3], z∈[0,4]  → three centre (1, 2, -2), normal +Z
const meshY = makePlane(COL.red, 'z', V(1, -2, 2));
// blue:  z = 2, x∈[-1,3], y∈[-3,1]  → three centre (1, 2, -1), normal +Y
const meshZ = makePlane(COL.blue, 'y', V(1, -1, 2));

/* ── Intersection lines ──────────────────────────────────────────────── */
function makeLine(col, a, b, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints([a.clone(), b.clone()]);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: col, dashSize: 0.14, gapSize: 0.1, depthTest: false })
    : new THREE.LineBasicMaterial({ color: col, depthTest: false });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  l.renderOrder = 6;
  scene.add(l);
  return {
    line: l,
    set(p, q) {
      const pos = l.geometry.attributes.position;
      pos.setXYZ(0, p.x, p.y, p.z);
      pos.setXYZ(1, q.x, q.y, q.z);
      pos.needsUpdate = true;
      if (dashed) l.computeLineDistances();
      l.geometry.computeBoundingSphere();
    }
  };
}

const lnGR = makeLine(mixDark(COL.green, COL.red), V(1, -2, 0), V(1, -2, 4));
const lnGB = makeLine(mixDark(COL.green, COL.blue), V(1, -3, 2), V(1, 1, 2));
const lnRB = makeLine(mixDark(COL.red, COL.blue), V(-1, -2, 2), V(3, -2, 2));

/* ── Solution dot, leader, mismatch connector ────────────────────────── */
const dot = new THREE.Mesh(
  new THREE.SphereGeometry(0.075, 20, 16),
  new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false })
);
dot.renderOrder = 12;
dot.position.copy(V(1, -1, 2));
scene.add(dot);

const LEAD = new THREE.Vector3(0.9, 2.2, -0.9);  // up-and-right on screen
const leader = makeLine(0x000000, dot.position, dot.position.clone().add(LEAD));
const connector = makeLine(0xE8A317, V(1, -1, 2), V(1, -2, 2), true);

/* ── Camera (after all core geometry) ────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.68
});
controls.minPolarAngle = 0.08;
controls.maxPolarAngle = Math.PI / 2 - 0.03;
document.getElementById('btnReset').style.display = '';

/* ── Focus arrows (added after fit; short, inside existing bounds) ───── */
function makeArrow(dir, origin, color) {
  const a = new THREE.ArrowHelper(dir.clone().normalize(), origin.clone(), 1.5, color, 0.38, 0.22);
  a.visible = false;
  a.renderOrder = 8;
  scene.add(a);
  return a;
}
const arrX = makeArrow(new THREE.Vector3(1, 0, 0), V(1, -1, 2), COL.green);
const arrY = makeArrow(new THREE.Vector3(0, 0, 1), V(1, -2, 2), COL.red);
const arrZ = makeArrow(new THREE.Vector3(0, 1, 0), V(1, -1, 2), COL.blue);

/* ── Labels ──────────────────────────────────────────────────────────── */
const labPoint = addLabel('(1, &minus;1, 2)', dot.position.clone().add(LEAD),
  { fontSize: '15px', offset: [26, -8] });
const labX = addLabel('<i>x</i> = 1', V(1, -3, 4),
  { color: '#22B14C', fontSize: '15px', offset: [28, -12] });
const labY = addLabel('<i>y</i> = &minus;2', V(1, -2, -0.4),
  { color: '#D62027', fontSize: '15px', offset: [0, 16] });
const labZ = addLabel('<i>z</i> = 2', V(3, -3, 2),
  { color: '#1878A0', fontSize: '15px', offset: [34, 0] });
const labWarn = addLabel('point not on <i>y</i> = &minus;2', V(1, -1.5, 2),
  { color: '#8a5a00', fontSize: '11px', background: 'rgba(255,224,150,0.92)', offset: [-14, 24] });
const labArrX = addLabel('<i>x</i> pinned at 1 &nbsp;(<i>y</i>, <i>z</i> free)', V(2.5, -1, 2),
  { color: '#1a8c3c', fontSize: '12px', bold: true, offset: [0, -16] });
const labArrY = addLabel('<i>y</i> pinned at &minus;2 &nbsp;(<i>x</i>, <i>z</i> free)', V(1, -0.5, 2),
  { color: '#c31a20', fontSize: '12px', bold: true, offset: [0, -16] });
const labArrZ = addLabel('<i>z</i> pinned at 2 &nbsp;(<i>x</i>, <i>y</i> free)', V(1, -1, 3.5),
  { color: '#14688c', fontSize: '12px', bold: true, offset: [0, -16] });

function setLabVis(entry, on) { entry.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── State + geometry update ─────────────────────────────────────────── */
const state = { redY: -2, dotY: -1, mode: 'printed', focus: null, showX: true, showY: true, showZ: true };

function applyGeometry() {
  meshY.position.z = state.redY;
  dot.position.z = state.dotY;

  lnGR.set(V(1, state.redY, 0), V(1, state.redY, 4));
  lnGB.set(V(1, -3, 2), V(1, 1, 2));
  lnRB.set(V(-1, state.redY, 2), V(3, state.redY, 2));

  leader.set(dot.position, dot.position.clone().add(LEAD));
  connector.set(dot.position, V(1, state.redY, 2));

  labPoint.pos.copy(dot.position).add(LEAD);
  labY.pos.copy(V(1, state.redY, -0.4));
  labWarn.pos.copy(V(1, (state.dotY + state.redY) / 2, 2));

  arrY.position.copy(V(1, state.redY, 2));
  labArrY.pos.copy(V(1, state.redY + 1.5, 2));
}

function updateTexts() {
  const yVal = state.mode === 'corrY' ? '&minus;1' : '&minus;2';
  labY.div.innerHTML = '<i>y</i> = ' + yVal;
  labArrY.div.innerHTML = '<i>y</i> pinned at ' + yVal + ' &nbsp;(<i>x</i>, <i>z</i> free)';
  labPoint.div.innerHTML = state.mode === 'corrPoint' ? '(1, &minus;2, 2)' : '(1, &minus;1, 2)';
  labWarn.div.innerHTML = 'point not on <i>y</i> = &minus;2';
  document.getElementById('lblShowY').innerHTML =
    'Show red plane <i>y</i> = ' + yVal;
}

function updateAppearance() {
  meshX.visible = state.showX;
  meshY.visible = state.showY;
  meshZ.visible = state.showZ;

  lnGR.line.visible = state.showX && state.showY;
  lnGB.line.visible = state.showX && state.showZ;
  lnRB.line.visible = state.showY && state.showZ;

  const op = (k) => state.focus === null ? 0.88 : (state.focus === k ? 1.0 : 0.22);
  meshX.material.opacity = op('x');
  meshY.material.opacity = op('y');
  meshZ.material.opacity = op('z');

  arrX.visible = state.focus === 'x' && state.showX;
  arrY.visible = state.focus === 'y' && state.showY;
  arrZ.visible = state.focus === 'z' && state.showZ;
  setLabVis(labArrX, arrX.visible);
  setLabVis(labArrY, arrY.visible);
  setLabVis(labArrZ, arrZ.visible);

  setLabVis(labX, state.showX);
  setLabVis(labY, state.showY);
  setLabVis(labZ, state.showZ);

  const warn = state.mode === 'printed' && state.showY;
  setLabVis(labWarn, warn);
  connector.line.visible = warn;
}

/* ── Mode tween (red sheet or dot slides along y over ~500 ms) ───────── */
const MODES = {
  printed: { redY: -2, dotY: -1 },
  corrY: { redY: -1, dotY: -1 },
  corrPoint: { redY: -2, dotY: -2 }
};
let tween = null;
function setMode(mode) {
  state.mode = mode;
  const to = MODES[mode];
  tween = { from: { redY: state.redY, dotY: state.dotY }, to, t0: performance.now(), dur: 500 };
  updateTexts();
  updateAppearance();
}
(function tick() {
  requestAnimationFrame(tick);
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    state.redY = tween.from.redY + (tween.to.redY - tween.from.redY) * e;
    state.dotY = tween.from.dotY + (tween.to.dotY - tween.from.dotY) * e;
    applyGeometry();
    if (k >= 1) tween = null;
  }
})();

/* ── Focus interaction ───────────────────────────────────────────────── */
function setFocus(k) {
  state.focus = (state.focus === k) ? null : k;
  updateAppearance();
}
[[labX, 'x'], [labY, 'y'], [labZ, 'z']].forEach(([L, k]) => {
  L.div.style.pointerEvents = 'auto';
  L.div.style.cursor = 'pointer';
  L.div.title = 'Click to highlight this plane';
  L.div.addEventListener('click', () => setFocus(k));
});

registerInteractive(meshX, {
  title: 'The plane x = 1',
  tooltip: 'Plane x = 1 — click to focus',
  body: 'Every point of this green sheet has x = 1; y and z may be anything. One equation in three unknowns describes a whole plane.',
  onClick: () => setFocus('x')
});
registerInteractive(meshY, {
  title: 'The plane y = constant',
  tooltip: 'Red plane — click to focus',
  body: 'This red sheet fixes y and leaves x and z free. As printed it is y = -2, which does not contain the point labelled (1, -1, 2).',
  onClick: () => setFocus('y')
});
registerInteractive(meshZ, {
  title: 'The plane z = 2',
  tooltip: 'Plane z = 2 — click to focus',
  body: 'Every point of this blue sheet has z = 2; x and y are free. Its intersection with x = 1 is a line, and the third plane cuts that line at one point.',
  onClick: () => setFocus('z')
});
document.getElementById('btnClearFocus').addEventListener('click', () => {
  state.focus = null; updateAppearance();
});

/* ── UI wiring ───────────────────────────────────────────────────────── */
const cbX = document.getElementById('showX');
const cbY = document.getElementById('showY');
const cbZ = document.getElementById('showZ');
[['showX', cbX], ['showY', cbY], ['showZ', cbZ]].forEach(([k, el]) => {
  el.addEventListener('change', () => { state[k] = el.checked; updateAppearance(); });
});

const rP = document.getElementById('lvPrinted');
const rY = document.getElementById('lvY');
const rPt = document.getElementById('lvP');
rP.addEventListener('change', () => rP.checked && setMode('printed'));
rY.addEventListener('change', () => rY.checked && setMode('corrY'));
rPt.addEventListener('change', () => rPt.checked && setMode('corrPoint'));

/* ── Guided demo ─────────────────────────────────────────────────────── */
const steps = [
  {
    title: '1 · One equation, one sheet',
    narr: 'Only the green plane x = 1 is shown: every point on this whole sheet satisfies x = 1, with y and z completely free.',
    s: { showX: true, showY: false, showZ: false, mode: 'printed' }
  },
  {
    title: '2 · Two equations, one line',
    narr: 'Adding the blue plane z = 2 leaves only the line where the two sheets meet — points satisfying both equations at once.',
    s: { showX: true, showY: false, showZ: true, mode: 'printed' }
  },
  {
    title: '3 · Three equations, one point',
    narr: 'The red sheet y = −2 cuts that line at a single point. This is the figure as printed — but the black dot is labelled (1, −1, 2), and −1 is not −2, so the marked point is not on the red sheet.',
    s: { showX: true, showY: true, showZ: true, mode: 'printed' }
  },
  {
    title: '4 · Fix the plane label',
    narr: 'Relabel the red sheet y = −1 and it now passes through (1, −1, 2): all three equations are satisfied at the marked point.',
    s: { showX: true, showY: true, showZ: true, mode: 'corrY' }
  },
  {
    title: '5 · Or fix the point label',
    narr: 'Alternatively keep y = −2 and move the marked point to (1, −2, 2). Either way, a solution must lie on every plane simultaneously.',
    s: { showX: true, showY: true, showZ: true, mode: 'corrPoint' }
  }
];
let stepIdx = 2;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const st = steps[stepIdx];
  cbX.checked = st.s.showX; cbY.checked = st.s.showY; cbZ.checked = st.s.showZ;
  state.showX = st.s.showX; state.showY = st.s.showY; state.showZ = st.s.showZ;
  rP.checked = st.s.mode === 'printed';
  rY.checked = st.s.mode === 'corrY';
  rPt.checked = st.s.mode === 'corrPoint';
  setMode(st.s.mode);
  document.getElementById('stepTitle').textContent = st.title;
  document.getElementById('stepNarr').textContent = st.narr;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── Initial state = figure as printed ───────────────────────────────── */
state.redY = -2; state.dotY = -1;
applyGeometry();
updateTexts();
updateAppearance();
document.getElementById('stepTitle').textContent = steps[2].title;
document.getElementById('stepNarr').textContent = steps[2].narr;
// @FIGURE_CODE_END

