// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ───────────────────────────────
 // green sheet x=1   → PlaneGeometry(4,4), rotY 90°,  MeshBasicMaterial #22B14C, DoubleSide, OPAQUE
 // red   sheet y     → PlaneGeometry(4,4), no rot,    MeshBasicMaterial #D8232A, DoubleSide, OPAQUE
 // blue  sheet z=2   → PlaneGeometry(4,4), rotX -90°, MeshBasicMaterial #1B7FA0, DoubleSide, OPAQUE
 // green∩red line    → Line, 2 pts, dark mix   (hidden by default)
 // green∩blue line   → Line, 2 pts, dark mix   (hidden by default)
 // red∩blue line     → Line, 2 pts, dark mix   (hidden by default)
 // marked point      → SphereGeometry(0.07), black, depthTest off
 // leader line       → Line, 2 pts, thin black, dot → label, depthTest off
 // mismatch link     → Line dashed amber (only when "label check" box is ticked)
 // normal arrows ×3  → ArrowHelper along each plane normal (hidden until focus)
 // labels            → addLabel: (1,−1,2) black · x = 1 green · y = −2 red · z = 2 blue
 ------------------------------------------------------------------------ */

// math (x, y, z) with z up  →  three.js (x, z, y)
const V = (x, y, z) => new THREE.Vector3(x, z, y);

const COL = { green: 0x22B14C, red: 0xD8232A, blue: 0x1B7FA0 };
const CSS = { green: '#1a8c3c', red: '#c31a20', blue: '#14688c' };

function mixDark(a, b) {
  const c = new THREE.Color(a).lerp(new THREE.Color(b), 0.5);
  c.multiplyScalar(0.5);
  return c;
}

/* ── Planes (opaque, exactly as printed: solid sheets cutting each other) ── */
function makePlane(color, normalAxis, centre) {
  const mat = new THREE.MeshBasicMaterial({
    color, side: THREE.DoubleSide, transparent: false, opacity: 1, depthWrite: true
  });
  const m = new THREE.Mesh(new THREE.PlaneGeometry(4, 4), mat);
  if (normalAxis === 'x') m.rotation.y = Math.PI / 2;    // normal → math +x
  if (normalAxis === 'z') m.rotation.x = -Math.PI / 2;   // normal → math +z (three +y)
  m.position.copy(centre);                               // normalAxis 'y' → no rotation
  scene.add(m);
  return m;
}

const PT = { x: 1, y: -1, z: 2 };                        // the marked point (1, −1, 2)

const meshX = makePlane(COL.green, 'x', V(PT.x, PT.y, PT.z));  // x = 1
const meshY = makePlane(COL.red, 'y', V(PT.x, PT.y, PT.z));  // y = const, through the point
const meshZ = makePlane(COL.blue, 'z', V(PT.x, PT.y, PT.z));  // z = 2

/* ── Pairwise intersection lines (off by default — not in the printed figure) */
function makeLine(col, a, b, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints([a.clone(), b.clone()]);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: col, dashSize: 0.13, gapSize: 0.1, depthTest: false })
    : new THREE.LineBasicMaterial({ color: col, depthTest: false });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  l.renderOrder = 6;
  l.visible = false;
  scene.add(l);
  return {
    line: l,
    set(p, q) {
      const pos = l.geometry.attributes.position;
      pos.setXYZ(0, p.x, p.y, p.z);
      pos.setXYZ(1, q.x, q.y, q.z);
      pos.needsUpdate = true;
      if (dashed) l.computeLineDistances();
      l.geometry.computeBoundingSphere();
    }
  };
}

const lnGR = makeLine(mixDark(COL.green, COL.red), V(1, -1, 0), V(1, -1, 4));
const lnGB = makeLine(mixDark(COL.green, COL.blue), V(1, -3, 2), V(1, 1, 2));
const lnRB = makeLine(mixDark(COL.red, COL.blue), V(-1, -1, 2), V(3, -1, 2));

/* ── Marked point + leader line ──────────────────────────────────────── */
const dot = new THREE.Mesh(
  new THREE.SphereGeometry(0.07, 20, 16),
  new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false })
);
dot.renderOrder = 12;
dot.position.copy(V(PT.x, PT.y, PT.z));
scene.add(dot);

const LEAD = V(0.3, -2.1, 2.1);              // up-and-right on screen, like the printed leader
const leader = makeLine(0x000000, dot.position, dot.position.clone().add(LEAD));
leader.line.visible = true;

const connector = makeLine(0xC98A10, V(1, -1, 2), V(1, -1, 2), true);   // shown only on request

/* ── Camera (all core geometry is in the scene) ──────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 24, z: 24 },
  heightFraction: 0.74
});
controls.minPolarAngle = 0.1;
controls.maxPolarAngle = Math.PI / 2 - 0.04;
document.getElementById('btnReset').style.display = '';

/* ── Normal arrows (created after the fit) ───────────────────────────── */
function makeArrow(dirMath, originMath, color) {
  const a = new THREE.ArrowHelper(
    V(dirMath[0], dirMath[1], dirMath[2]).normalize(),
    originMath.clone(), 1.5, color, 0.36, 0.2
  );
  a.visible = false;
  a.renderOrder = 8;
  scene.add(a);
  return a;
}
const arrX = makeArrow([1, 0, 0], V(PT.x, PT.y, PT.z), COL.green);
const arrY = makeArrow([0, 1, 0], V(PT.x, PT.y, PT.z), COL.red);
const arrZ = makeArrow([0, 0, 1], V(PT.x, PT.y, PT.z), COL.blue);

/* ── Labels ──────────────────────────────────────────────────────────── */
function serif(entry) {
  entry.div.style.fontFamily = 'Cambria, "Times New Roman", Georgia, serif';
  return entry;
}
const labPoint = serif(addLabel('(1, &minus;1, 2)', dot.position.clone().add(LEAD),
  { fontSize: '16px', offset: [36, -8] }));
const labX = serif(addLabel('<i>x</i> = 1', V(1, -3, 4),
  { color: CSS.green, fontSize: '16px', offset: [26, -10] }));
const labY = serif(addLabel('<i>y</i> = &minus;2', V(1, -1, -0.35),
  { color: CSS.red, fontSize: '16px', offset: [0, 16] }));
const labZ = serif(addLabel('<i>z</i> = 2', V(3, -3, 2),
  { color: CSS.blue, fontSize: '16px', offset: [34, 0] }));

const labArrX = addLabel('<i>x</i> pinned at 1 &nbsp;(<i>y</i>, <i>z</i> free)', V(2.9, -1, 2),
  { color: CSS.green, fontSize: '12px', bold: true, offset: [0, -14] });
const labArrY = addLabel('<i>y</i> pinned &nbsp;(<i>x</i>, <i>z</i> free)', V(1, 0.7, 2),
  { color: CSS.red, fontSize: '12px', bold: true, offset: [0, -14] });
const labArrZ = addLabel('<i>z</i> pinned at 2 &nbsp;(<i>x</i>, <i>y</i> free)', V(1, -1, 3.8),
  { color: CSS.blue, fontSize: '12px', bold: true, offset: [0, -14] });
const labGap = addLabel('the point is not on <i>y</i> = &minus;2', V(1, -1.5, 2),
  { color: '#8a5a00', fontSize: '11px', background: 'rgba(255,236,190,0.95)', offset: [-6, 22] });

function setLabVis(e, on) { e.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── State ───────────────────────────────────────────────────────────── */
const state = {
  showX: true, showY: true, showZ: true, showLines: false,
  mode: 'printed', mismatch: false, focus: null,
  redY: -1                     // animated: −1 (through the point, as drawn) or −2
};

function applyGeometry() {
  meshY.position.copy(V(1, state.redY, 2));
  lnGR.set(V(1, state.redY, 0), V(1, state.redY, 4));
  lnGB.set(V(1, -3, 2), V(1, 1, 2));
  lnRB.set(V(-1, state.redY, 2), V(3, state.redY, 2));
  connector.set(V(PT.x, PT.y, PT.z), V(1, state.redY, 2));
  labY.pos.copy(V(1, state.redY, -0.35));
  arrY.position.copy(V(1, state.redY, 2));
  labArrY.pos.copy(V(1, state.redY + 1.8, 2));
  labGap.pos.copy(V(1, (PT.y + state.redY) / 2, 2));
}

function updateTexts() {
  const yTxt = state.mode === 'corrY' ? '&minus;1' : '&minus;2';
  labY.div.innerHTML = '<i>y</i> = ' + yTxt;
  labArrY.div.innerHTML = '<i>y</i> pinned at ' + yTxt + ' &nbsp;(<i>x</i>, <i>z</i> free)';
  labPoint.div.innerHTML = state.mode === 'corrPoint' ? '(1, &minus;2, 2)' : '(1, &minus;1, 2)';
  document.getElementById('lblShowY').innerHTML = 'Show red sheet <i>y</i> = ' + yTxt;
}

function styleMesh(mesh, focused, anyFocus) {
  const m = mesh.material;
  if (!anyFocus || focused) {
    m.transparent = false; m.opacity = 1; m.depthWrite = true;
  } else {
    m.transparent = true; m.opacity = 0.16; m.depthWrite = false;
  }
  m.needsUpdate = true;
}

function updateAppearance() {
  meshX.visible = state.showX;
  meshY.visible = state.showY;
  meshZ.visible = state.showZ;

  const any = state.focus !== null;
  styleMesh(meshX, state.focus === 'x', any);
  styleMesh(meshY, state.focus === 'y', any);
  styleMesh(meshZ, state.focus === 'z', any);

  lnGR.line.visible = state.showLines && state.showX && state.showY;
  lnGB.line.visible = state.showLines && state.showX && state.showZ;
  lnRB.line.visible = state.showLines && state.showY && state.showZ;

  arrX.visible = state.focus === 'x' && state.showX;
  arrY.visible = state.focus === 'y' && state.showY;
  arrZ.visible = state.focus === 'z' && state.showZ;
  setLabVis(labArrX, arrX.visible);
  setLabVis(labArrY, arrY.visible);
  setLabVis(labArrZ, arrZ.visible);

  setLabVis(labX, state.showX);
  setLabVis(labY, state.showY);
  setLabVis(labZ, state.showZ);

  const gap = state.mismatch && state.mode === 'printed' && state.showY;
  setLabVis(labGap, gap);
  connector.line.visible = gap;

  document.getElementById('cbMismatch').disabled = state.mode !== 'printed';
}

/* ── Smooth slide of the red sheet ───────────────────────────────────── */
let tween = null;
function targetRedY() {
  return (state.mismatch && state.mode === 'printed') ? -2 : -1;
}
function retarget() {
  const to = targetRedY();
  if (Math.abs(to - state.redY) < 1e-4) { state.redY = to; applyGeometry(); return; }
  tween = { from: state.redY, to, t0: performance.now(), dur: 520 };
}
(function tick() {
  requestAnimationFrame(tick);
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    state.redY = tween.from + (tween.to - tween.from) * e;
    applyGeometry();
    if (k >= 1) tween = null;
  }
})();

/* ── Focus interaction ───────────────────────────────────────────────── */
function setFocus(k) {
  state.focus = (state.focus === k) ? null : k;
  updateAppearance();
}
[[labX, 'x'], [labY, 'y'], [labZ, 'z']].forEach(([L, k]) => {
  L.div.style.pointerEvents = 'auto';
  L.div.style.cursor = 'pointer';
  L.div.title = 'Click to highlight this plane';
  L.div.addEventListener('click', () => setFocus(k));
});

registerInteractive(meshX, {
  title: 'The plane x = 1',
  tooltip: 'Plane x = 1 — click to focus',
  body: 'Every point of this green sheet has x = 1, while y and z stay completely free. A single linear equation in three unknowns describes a whole plane.',
  onClick: () => setFocus('x')
});
registerInteractive(meshY, {
  title: 'The plane y = −2',
  tooltip: 'Red plane — click to focus',
  body: 'This red sheet fixes y and leaves x and z free. It is parallel to the xz-plane and cuts both of the other sheets.',
  onClick: () => setFocus('y')
});
registerInteractive(meshZ, {
  title: 'The plane z = 2',
  tooltip: 'Plane z = 2 — click to focus',
  body: 'Every point of this blue sheet has z = 2; x and y are free. Its intersection with x = 1 is a line, and the third sheet cuts that line at exactly one point.',
  onClick: () => setFocus('z')
});
registerInteractive(dot, {
  title: 'The common point',
  tooltip: 'The point where all three sheets meet',
  body: 'All three equations hold simultaneously only here: the solution of the system is the single point where the three planes meet.'
});
document.getElementById('btnClearFocus').addEventListener('click', () => {
  state.focus = null; updateAppearance();
});

/* ── UI wiring ───────────────────────────────────────────────────────── */
const cbX = document.getElementById('showX');
const cbY = document.getElementById('showY');
const cbZ = document.getElementById('showZ');
const cbL = document.getElementById('showLines');
const cbM = document.getElementById('cbMismatch');
[['showX', cbX], ['showY', cbY], ['showZ', cbZ], ['showLines', cbL]].forEach(([k, el]) => {
  el.addEventListener('change', () => { state[k] = el.checked; updateAppearance(); });
});
cbM.addEventListener('change', () => {
  state.mismatch = cbM.checked; retarget(); updateAppearance();
});

const rP = document.getElementById('lvPrinted');
const rY = document.getElementById('lvY');
const rPt = document.getElementById('lvP');
function setMode(m) {
  state.mode = m;
  if (m !== 'printed') { state.mismatch = false; cbM.checked = false; }
  retarget(); updateTexts(); updateAppearance();
}
rP.addEventListener('change', () => rP.checked && setMode('printed'));
rY.addEventListener('change', () => rY.checked && setMode('corrY'));
rPt.addEventListener('change', () => rPt.checked && setMode('corrPoint'));

/* ── Guided demo ─────────────────────────────────────────────────────── */
const steps = [
  {
    title: '1 · One equation → a sheet',
    narr: 'Only x = 1 is shown. Every point of this entire green plane satisfies the equation; y and z remain free, so one equation leaves a two-parameter family of solutions.',
    s: { showX: true, showY: false, showZ: false, lines: false, mode: 'printed', mismatch: false }
  },
  {
    title: '2 · Two equations → a line',
    narr: 'Add z = 2. Only the line where the green and blue sheets meet satisfies both equations: one free parameter is left.',
    s: { showX: true, showY: false, showZ: true, lines: true, mode: 'printed', mismatch: false }
  },
  {
    title: '3 · Three equations → a point',
    narr: 'The red sheet cuts that line at a single point — the marked point (1, −1, 2). This is the figure exactly as printed: three coordinate-parallel planes meeting at one solution.',
    s: { showX: true, showY: true, showZ: true, lines: true, mode: 'printed', mismatch: false }
  },
  {
    title: '4 · Do the labels agree?',
    narr: 'Drawn at the y it is labelled with, y = −2, the red sheet slides one unit away from the marked point: the printed labels (1, −1, 2) and y = −2 cannot both be right.',
    s: { showX: true, showY: true, showZ: true, lines: false, mode: 'printed', mismatch: true }
  },
  {
    title: '5 · Two ways to repair it',
    narr: 'Relabel the sheet y = −1 and it passes through (1, −1, 2) again. Or keep y = −2 and read the point as (1, −2, 2). Either way, a solution must lie on every plane at once.',
    s: { showX: true, showY: true, showZ: true, lines: true, mode: 'corrY', mismatch: false }
  }
];
let stepIdx = -1;
function applyStep(st) {
  cbX.checked = state.showX = st.showX;
  cbY.checked = state.showY = st.showY;
  cbZ.checked = state.showZ = st.showZ;
  cbL.checked = state.showLines = st.lines;
  rP.checked = st.mode === 'printed';
  rY.checked = st.mode === 'corrY';
  rPt.checked = st.mode === 'corrPoint';
  state.mode = st.mode;
  state.mismatch = st.mismatch;
  cbM.checked = st.mismatch;
  retarget(); updateTexts(); updateAppearance();
}
const elTitle = document.getElementById('stepTitle');
const elNarr = document.getElementById('stepNarr');
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const st = steps[stepIdx];
  applyStep(st.s);
  elTitle.textContent = st.title;
  elNarr.textContent = st.narr;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnDemoReset').addEventListener('click', () => { stepIdx = -1; showPrinted(); });

/* ── Initial state = the figure exactly as printed ───────────────────── */
function showPrinted() {
  applyStep({ showX: true, showY: true, showZ: true, lines: false, mode: 'printed', mismatch: false });
  state.focus = null;
  updateAppearance();
  elTitle.textContent = 'The figure as printed';
  elNarr.textContent = 'Press Next ▶ to build the picture one equation at a time.';
}
state.redY = -1;
applyGeometry();
showPrinted();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
