// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ───────────────────────────────
 // green sheet x = 1  → PlaneGeometry(4.6 wide in y, 2.2 tall in z), rotY 90°,
 //                      MeshBasicMaterial #22B14C, DoubleSide, OPAQUE, centre (1,-1.1,2.0)
 // red sheet  y = c   → PlaneGeometry(3.4 wide in x, 3.2 tall in z), no rotation,
 //                      MeshBasicMaterial #D8232A, DoubleSide, OPAQUE, centre (0.9, c, 2.1)
 // blue sheet z = 2   → PlaneGeometry(2.8 wide in x, 4.0 deep in y), rotX -90°,
 //                      MeshBasicMaterial #1379A6, DoubleSide, OPAQUE, centre (0.9,-1.1,2)
 //   (deliberately three DIFFERENT rectangles with slightly off-centre placement,
 //    like the printed figure — not a symmetric pinwheel of equal squares)
 // green∩red line     → Line, 2 pts, dark mix   (hidden by default)
 // green∩blue line    → Line, 2 pts, dark mix   (hidden by default)
 // red∩blue line      → Line, 2 pts, dark mix   (hidden by default)
 // marked point       → SphereGeometry(0.075), black, depthTest off
 // leader line        → Line, 2 pts, thin black, dot → label, depthTest off
 // mismatch link      → dashed amber Line (only when the label-check box is ticked)
 // normal arrows ×3   → ArrowHelper along each plane normal (hidden until focus)
 // labels             → addLabel: (1,−1,2) black · x = 1 green · y = −2 red · z = 2 blue
 ------------------------------------------------------------------------ */

// math (x, y, z) with z up  →  three.js (x, z, y)
const V = (x, y, z) => new THREE.Vector3(x, z, y);

const COL = { green: 0x22B14C, red: 0xD8232A, blue: 0x1379A6 };
const CSS = { green: '#1a8c3c', red: '#c31a20', blue: '#11678f' };

// rectangle extents (math coords) — intentionally unequal, as printed
const RECT = {
  green: { y: [-3.4, 1.2], z: [0.90, 3.10] },  // x = 1
  red: { x: [-0.8, 2.6], z: [0.50, 3.70] },  // y = const
  blue: { x: [-0.5, 2.3], y: [-3.10, 0.90] } // z = 2
};
const mid = (r) => (r[0] + r[1]) / 2;
const len = (r) => (r[1] - r[0]);

function mixDark(a, b) {
  const c = new THREE.Color(a).lerp(new THREE.Color(b), 0.5);
  c.multiplyScalar(0.5);
  return c;
}

const PT = { x: 1, y: -1, z: 2 };                        // the marked point (1, −1, 2)

/* ── Planes (opaque sheets cutting through each other) ───────────────── */
function newPlaneMat(color) {
  return new THREE.MeshBasicMaterial({
    color, side: THREE.DoubleSide, transparent: false, opacity: 1, depthWrite: true
  });
}

// green: x = 1, spans math y (width) and math z (height)
const meshX = new THREE.Mesh(
  new THREE.PlaneGeometry(len(RECT.green.y), len(RECT.green.z)), newPlaneMat(COL.green));
meshX.rotation.y = Math.PI / 2;
meshX.position.copy(V(1, mid(RECT.green.y), mid(RECT.green.z)));
scene.add(meshX);

// red: y = const, spans math x (width) and math z (height)
const meshY = new THREE.Mesh(
  new THREE.PlaneGeometry(len(RECT.red.x), len(RECT.red.z)), newPlaneMat(COL.red));
meshY.position.copy(V(mid(RECT.red.x), PT.y, mid(RECT.red.z)));
scene.add(meshY);

// blue: z = 2, spans math x (width) and math y (depth)
const meshZ = new THREE.Mesh(
  new THREE.PlaneGeometry(len(RECT.blue.x), len(RECT.blue.y)), newPlaneMat(COL.blue));
meshZ.rotation.x = -Math.PI / 2;
meshZ.position.copy(V(mid(RECT.blue.x), mid(RECT.blue.y), 2));
scene.add(meshZ);

/* ── Pairwise intersection lines (off by default — not in the printed figure) */
function makeLine(col, a, b, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints([a.clone(), b.clone()]);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: col, dashSize: 0.13, gapSize: 0.1, depthTest: false })
    : new THREE.LineBasicMaterial({ color: col, depthTest: false });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  l.renderOrder = 6;
  l.visible = false;
  scene.add(l);
  return {
    line: l,
    set(p, q) {
      const pos = l.geometry.attributes.position;
      pos.setXYZ(0, p.x, p.y, p.z);
      pos.setXYZ(1, q.x, q.y, q.z);
      pos.needsUpdate = true;
      if (dashed) l.computeLineDistances();
      l.geometry.computeBoundingSphere();
    }
  };
}

const lnGR = makeLine(mixDark(COL.green, COL.red), V(1, -1, 0.9), V(1, -1, 3.1));
const lnGB = makeLine(mixDark(COL.green, COL.blue), V(1, -3.1, 2), V(1, 0.9, 2));
const lnRB = makeLine(mixDark(COL.red, COL.blue), V(-0.5, -1, 2), V(2.3, -1, 2));

/* ── Marked point + leader line ──────────────────────────────────────── */
const dot = new THREE.Mesh(
