  a.visible = false;
  a.renderOrder = 8;
  scene.add(a);
  return a;
}
const arrX = makeArrow([1, 0, 0], V(PT.x, PT.y, PT.z), COL.green);
const arrY = makeArrow([0, 1, 0], V(PT.x, PT.y, PT.z), COL.red);
const arrZ = makeArrow([0, 0, 1], V(PT.x, PT.y, PT.z), COL.blue);

/* ── Labels ──────────────────────────────────────────────────────────── */
function serif(entry) {
  entry.div.style.fontFamily = 'Cambria, "Times New Roman", Georgia, serif';
  return entry;
}
// point label: top of the frame, at the far end of the leader (up-left of "x = 1")
const labPoint = serif(addLabel('(1, &minus;1, 2)', TIP.clone(),
  { fontSize: '17px', offset: [48, -4] }));
// "x = 1" hangs off the upper-right corner of the green sheet, well below the point label
const labX = serif(addLabel('<i>x</i> = 1', V(1, RECT.green.y[0], RECT.green.z[1]),
  { color: CSS.green, fontSize: '17px', offset: [32, -4] }));
// "y = −2" below the bottom edge of the red sheet
const labY = serif(addLabel('<i>y</i> = &minus;2', V(0.55, PT.y, RECT.red.z[0]),
  { color: CSS.red, fontSize: '17px', offset: [-4, 26] }));
// "z = 2" at the right-hand tip of the blue sheet
const labZ = serif(addLabel('<i>z</i> = 2', V(RECT.blue.x[1], RECT.blue.y[0], 2),
